def unique_justseen(iterable, key=None):
    """Yields elements in order, ignoring serial duplicates

    >>> list(unique_justseen('AAAABBBCCDAABBB'))
    ['A', 'B', 'C', 'D', 'A', 'B']
    >>> list(unique_justseen('ABBCcAD', str.lower))
    ['A', 'B', 'C', 'A', 'D']

    """
    from itertools import groupby

    if key is None:
        for _, group in groupby(iterable):
            yield next(group)
    else:
        for _, group in groupby(iterable, key):
            yield next(group)

from itertools import zip_longest

def grouper(iterable, n, incomplete='fill', fillvalue=None):
    """Group elements from *iterable* into fixed-length groups of length *n*.

    >>> list(grouper('ABCDEF', 3))
    [('A', 'B', 'C'), ('D', 'E', 'F')]

    The keyword arguments *incomplete* and *fillvalue* control what happens for
    iterables whose length is not a multiple of *n*.

    When *incomplete* is `'fill'`, the last group will contain instances of
    *fillvalue*.

    >>> list(grouper('ABCDEFG', 3, incomplete='fill', fillvalue='x'))
    [('A', 'B', 'C'), ('D', 'E', 'F'), ('G', 'x', 'x')]

    When *incomplete* is `'ignore'`, the last group will not be emitted.

    >>> list(grouper('ABCDEFG', 3, incomplete='ignore', fillvalue='x'))
    [('A', 'B', 'C'), ('D', 'E', 'F')]

    When *incomplete* is `'strict'`, a `ValueError` will be raised.

    >>> iterator = grouper('ABCDEFG', 3, incomplete='strict')
    >>> list(iterator)  # doctest: +IGNORE_EXCEPTION_DETAIL
    Traceback (most recent call last):
    ...
    ValueError

    """
    if incomplete == 'fill':
        return zip_longest(*([iter(iterable)] * n), fillvalue=fillvalue)
    elif incomplete == 'ignore':
        return zip(*([iter(iterable)] * n))
    elif incomplete == 'strict':
        for element in zip(*([iter(iterable)] * n)):
            if any(x is None for x in element):
                raise ValueError("The length of the iterable is not a multiple of n")
        return zip(*([iter(iterable)] * n))
    else:
        raise ValueError("Invalid value for 'incomplete' keyword argument")

